import{_ as l,a0 as t,w as o,s as d,I as n,x as a,a1 as i,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中使用旧相机作为网络摄像头 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用旧相机作为网络摄像头 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用旧相机作为网络摄像头 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用旧相机作为网络摄像头 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20221219.1 ⭐️⭐️ How I use my old camera as a webcam with Linux","title":"如何在 Linux 中使用旧相机作为网络摄像头","tag":"202303","desc":""},"relativePath":"202303/20221219.1 ⭐️⭐️ How I use my old camera as a webcam with Linux.md","filePath":"[post].md"}'),c={name:"202303/20221219.1 ⭐️⭐️ How I use my old camera as a webcam with Linux.md"};function h(u,s,g,b,k,m){const e=t("Link");return o(),d("div",null,[s[18]||(s[18]=n("h1",{id:"如何在-linux-中使用旧相机作为网络摄像头",tabindex:"-1"},[a("如何在 Linux 中使用旧相机作为网络摄像头 "),n("a",{class:"header-anchor",href:"#如何在-linux-中使用旧相机作为网络摄像头","aria-label":"Permalink to “如何在 Linux 中使用旧相机作为网络摄像头”"},"​")],-1)),s[19]||(s[19]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202303/21/233633z1qxdoq1shrx1xmc.jpg",alt:""})],-1)),s[20]||(s[20]=n("blockquote",null,[n("p",null,"我用 gphoto2 给我的旧单反相机带来了新的生命，把它变成了 Linux 电脑的网络摄像头。")],-1)),s[21]||(s[21]=n("p",null,"今年，在我基本上放弃了 MacBook，转而使用 NixOS 机器之后，我开始在与人进行视频通话时被要求“打开摄像头”。这是一个问题，因为我没有网络摄像头。我考虑购买一个，但后来我意识到我有一台完好无损的 2008 年产的佳能 EOS Rebel XS 数码单反相机放在书架上。这台相机有一个 mini-USB 接口，所以我自然而然地思考：一台数码单反相机、一个 mini-USB 接口和一台台式电脑，是否意味着我能拥有一个网络摄像头？",-1)),s[22]||(s[22]=n("p",null,"只有一个问题。我的佳能 EOS Rebel XS 不能录制视频。它可以拍摄一些漂亮的照片，仅此而已。所以这结束了？",-1)),s[23]||(s[23]=n("p",null,"还是有别的办法？",-1)),n("p",null,[s[1]||(s[1]=a("恰好有一个叫做 ",-1)),i(e,{href:"http://gphoto.org/"},{default:p(()=>[...s[0]||(s[0]=[a("gphoto2",-1)])]),_:1}),s[2]||(s[2]=a(" 的神奇的开源软件。一旦安装，它允许你从计算机控制各种支持的相机，并拍摄照片和视频。",-1))]),s[24]||(s[24]=r(`<h3 id="支持的相机" tabindex="-1">支持的相机 <a class="header-anchor" href="#支持的相机" aria-label="Permalink to “支持的相机”">​</a></h3><p>首先，了解你的设备是否得到支持：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --list-cameras</span></span></code></pre></div><h3 id="拍摄图像" tabindex="-1">拍摄图像 <a class="header-anchor" href="#拍摄图像" aria-label="Permalink to “拍摄图像”">​</a></h3><p>你可以用它拍照：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --capture-image-and-download</span></span></code></pre></div><p>快门触发，图像会保存到你当前的工作目录中。</p><h3 id="录制视频" tabindex="-1">录制视频 <a class="header-anchor" href="#录制视频" aria-label="Permalink to “录制视频”">​</a></h3><p>我意识到了这里的潜力，所以尽管我的相机没有视频功能，我还是决定尝试 <code>gphoto2 --capture-movie</code> 命令。不知怎么，尽管我的相机不支持视频功能，<code>gphoto2</code> 仍然能够生成一个 MJPEG 文件！</p><p>在我的相机上，我需要将其置于“实时预览”模式下，然后 <code>gphoto2</code> 才能录制视频。这包括将相机设置为纵向模式，然后按下 “<ruby>设置<rt>Set</rt></ruby>” 按钮，使取景器关闭，相机屏幕显示图像。不幸的是，这还不足以将其用作网络摄像头。它仍然需要分配一个视频设备，例如 <code>/dev/video0</code>。</p><h3 id="安装-ffmpeg-和-v4l2loopback" tabindex="-1">安装 ffmpeg 和 v4l2loopback <a class="header-anchor" href="#安装-ffmpeg-和-v4l2loopback" aria-label="Permalink to “安装 ffmpeg 和 v4l2loopback”">​</a></h3><p>毫不奇怪，有一个开源的解决方案来解决这个问题。首先，使用你的包管理器安装 <code>gphoto2</code>、<code>ffmpeg</code> 和 <code>mpv</code>。例如，在 Fedora 、CentOS 、Mageia 和类似的 Linux 发行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gphoto2 ffmpeg mpv</span></span></code></pre></div><p>在 Debian、Linux Mint 及其类似发行版:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gphoto2 ffmpeg mpv</span></span></code></pre></div><p>我使用的是 NixOS，这是我的配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># configuration.nix</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>environment.systemPackages = with pkgs; [</span></span>
<span class="line"><span>  ffmpeg</span></span>
<span class="line"><span>  gphoto2</span></span>
<span class="line"><span>  mpv</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>创建虚拟视频设备需要使用 <code>v4l2loopback</code> Linux 内核模块。在撰写本文时，该功能未包含在主线内核中，因此你需要自己下载和编译它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/umlaeute/v4l2loopback</span></span>
<span class="line"><span>$ cd v4l2loopback</span></span>
<span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span>
<span class="line"><span>$ sudo depmod -a</span></span></code></pre></div><p>如果你像我一样使用 NixOS ，你可以在 <code>configuration.nix</code> 中添加额外的模块包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>boot.extraModulePackages = with config.boot.kernelPackages;</span></span>
<span class="line"><span>[ v4l2loopback.out ];</span></span>
<span class="line"><span>boot.kernelModules = [</span></span>
<span class="line"><span>  &quot;v4l2loopback&quot;</span></span>
<span class="line"><span>];</span></span>
<span class="line"><span>boot.extraModprobeConfig = &#39;&#39;</span></span>
<span class="line"><span>  options v4l2loopback exclusive_caps=1 card_label=&quot;Virtual Camera&quot;</span></span>
<span class="line"><span>&#39;&#39;;</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>在 NixOS 上, 运行 <code>sudo nixos-rebuild switch</code>，然后重启。</p><h3 id="创建一个视频设备" tabindex="-1">创建一个视频设备 <a class="header-anchor" href="#创建一个视频设备" aria-label="Permalink to “创建一个视频设备”">​</a></h3><p>假设你的计算机当前没有 <code>/dev/video</code> 设备，你可以借助 <code>v4l2loopback</code> 在需要时创建一个。</p><p>运行以下命令，将 <code>gphoto2</code> 中的数据发送到 <code>ffmpeg</code>，使用设备如 <code>/dev/video0</code> 设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --stdout --capture-movie |</span></span>
<span class="line"><span> ffmpeg -i - -vcodec rawvideo -pix_fmt yuv420p -f v4l2 /dev/video0</span></span></code></pre></div><p>你得到的输出是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ffmpeg version 4.4.1 Copyright (c) 2000-2021 the FFmpeg developers</span></span>
<span class="line"><span>  built with gcc 11.3.0 (GCC)</span></span>
<span class="line"><span>  configuration: --disable-static ...</span></span>
<span class="line"><span>  libavutil      56. 70.100 / 56. 70.100</span></span>
<span class="line"><span>  libavcodec     58.134.100 / 58.134.100</span></span>
<span class="line"><span>  libavformat    58. 76.100 / 58. 76.100</span></span>
<span class="line"><span>  libavdevice    58. 13.100 / 58. 13.100</span></span>
<span class="line"><span>  libavfilter     7.110.100 /  7.110.100</span></span>
<span class="line"><span>  libavresample   4.  0.  0 /  4.  0.  0</span></span>
<span class="line"><span>  libswscale      5.  9.100 /  5.  9.100</span></span>
<span class="line"><span>  libswresample   3.  9.100 /  3.  9.100</span></span>
<span class="line"><span>  libpostproc    55.  9.100 / 55.  9.100</span></span>
<span class="line"><span>Capturing preview frames as movie to &#39;stdout&#39;. Press Ctrl-C to abort.[mjpeg @ 0x1dd0380] Format mjpeg detected only with low score of 25, misdetection possible!</span></span>
<span class="line"><span>Input #0, mjpeg, from &#39;pipe:&#39;:</span></span>
<span class="line"><span>  Duration: N/A, bitrate: N/A</span></span>
<span class="line"><span>  Stream #0:0: Video: mjpeg (Baseline), yuvj422p(pc, bt470bg/unknown/unknown), 768x512 ...</span></span>
<span class="line"><span>Stream mapping:</span></span>
<span class="line"><span>  Stream #0:0 -&gt; #0:0 (mjpeg (native) -&gt; rawvideo (native))[swscaler @ 0x1e27340] deprecated pixel format used, make sure you did set range correctly</span></span>
<span class="line"><span>Output #0, video4linux2,v4l2, to &#39;/dev/video0&#39;:</span></span>
<span class="line"><span>  Metadata:</span></span>
<span class="line"><span>    encoder         : Lavf58.76.100</span></span>
<span class="line"><span>  Stream #0:0: Video: rawvideo (I420 / 0x30323449) ...</span></span>
<span class="line"><span>    Metadata:</span></span>
<span class="line"><span>      encoder         : Lavc58.134.100 rawvideoframe=  289 fps= 23 q=-0.0 size=N/A time=00:00:11.56 bitrate=N/A speed=0.907x</span></span></code></pre></div><p>要查看来自网络摄像头的视频，请使用 <code>mpv</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mpv av://v4l2:/dev/video0 --profile=low-latency --untimed</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/2022-12/streaming-webcam.png" alt="Streaming a live feed from the webcam"></p><h3 id="自动启动你的网络摄像头" tabindex="-1">自动启动你的网络摄像头 <a class="header-anchor" href="#自动启动你的网络摄像头" aria-label="Permalink to “自动启动你的网络摄像头”">​</a></h3><p>每次想使用网络摄像头时都需要执行一次命令有点麻烦。幸运的是，你可以在启动时自动运行此命令。我将其实现为一个 <code>systemd</code> 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># configuration.nix</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>  systemd.services.webcam = {</span></span>
<span class="line"><span>    enable = true;</span></span>
<span class="line"><span>    script = &#39;&#39;</span></span>
<span class="line"><span>      \${pkgs.gphoto2}/bin/gphoto2 --stdout --capture-movie |</span></span>
<span class="line"><span>        \${pkgs.ffmpeg}/bin/ffmpeg -i - \\</span></span>
<span class="line"><span>            -vcodec rawvideo -pix_fmt yuv420p -f v4l2  /dev/video0</span></span>
<span class="line"><span>    &#39;&#39;;</span></span>
<span class="line"><span>wantedBy = [ &quot;multi-user.target&quot; ];</span></span>
<span class="line"><span>  };</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>在 NixOS 上，运行 <code>sudo nixos-rebuild switch</code>，然后重新启动你的计算机。你的网络摄像头已经开启并处于活动状态。</p><p>要检查是否存在任何问题，可以使用 <code>systemctl status webcam</code> 命令。它会告诉你服务最后一次运行的时间，并提供其以前输出的日志。这对于调试非常有用。</p><h3 id="迭代以使其变得更好" tabindex="-1">迭代以使其变得更好 <a class="header-anchor" href="#迭代以使其变得更好" aria-label="Permalink to “迭代以使其变得更好”">​</a></h3><p>止步于此也许很诱人。但是，考虑到当前的全球危机，我们可能需要思考是否有必要一直开着网络摄像头。这让我感到不太理想，原因如下：</p><ul><li>这浪费电。</li><li>这类事情涉及隐私问题。</li></ul><p>我的摄像头有一个镜头盖，所以说实话，第二个原因并不真的让我感到困扰。当我不使用网络摄像头时，我总是可以把镜头盖上。然而，让一个耗电量大的单反相机整天开着（更不用说需要解码视频所需的 CPU 开销），对我的电费并没有任何好处。</p><p>理想情况是：</p><ul><li>我一直把相机插在电脑上，但是关闭的。</li><li>当我想使用网络摄像头时，我按下相机的电源按钮将其打开。</li><li>我的计算机会检测到相机并启动 systemd 服务。</li><li>使用网络摄像头完成后，我再次将其关闭。</li></ul><p>为了实现这一点，你需要使用一个自定义的 udev 规则。</p><p>udev 规则可以告诉你的计算机，当它发现某个设备已经可用时执行某个任务。这可以是外部硬盘甚至是非 USB 设备。在这种情况下，你需要通过其 USB 连接识别相机。</p><p>首先，指定 udev 规则被触发时要运行的命令。你可以用一个 shell 脚本来完成（<code>systemctl restart webcam</code> 应该可以工作）。我运行的是 NixOS，所以我只需要创建一个派生包（一个 Nix 包），它会重新启动 systemd 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># start-webcam.nix</span></span>
<span class="line"><span>with import &lt;nixpkgs&gt; { };</span></span>
<span class="line"><span>writeShellScriptBin &quot;start-webcam&quot; &#39;&#39;</span></span>
<span class="line"><span>  systemctl restart webcam</span></span>
<span class="line"><span>  # debugging example</span></span>
<span class="line"><span>  # echo &quot;hello&quot; &amp;&gt; /home/tom/myfile.txt</span></span>
<span class="line"><span>  # If myfile.txt gets created then we know the udev rule has triggered properly&#39;&#39;</span></span></code></pre></div><p>接下来，实际定义 udev 规则。查找摄像头的设备和厂商 ID。使用 <code>lsusb</code> 命令可以完成此操作。该命令可能已经安装在你的发行版上，但我不经常使用它，因此我只需要根据需要使用 <code>nix-shell</code> 安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nix-shell -p usbutils</span></span></code></pre></div><p>无论你的计算机上已经安装了它，还是刚刚安装，请运行 <code>lsusb</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb</span></span>
<span class="line"><span>Bus 002 Device 008: ID 04a9:317b Canon, Inc. Canon Digital Camera[...]</span></span></code></pre></div><p>在此输出中，厂商 ID 为 <code>04a9</code>，设备 ID 为 <code>317b</code>。这已足以创建 udev 规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ACTION==&quot;add&quot;, SUBSYSTEM==&quot;usb&quot;,</span></span>
<span class="line"><span>ATTR{idVendor}==&quot;04a9&quot;,</span></span>
<span class="line"><span>ATTR{idProduct}==&quot;317b&quot;,</span></span>
<span class="line"><span>RUN+=&quot;/usr/local/bin/start-webcam.sh&quot;</span></span></code></pre></div><p>或者，如果你使用的是 NixOS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># configuration.nix[...]let</span></span>
<span class="line"><span>  startWebcam = import ./start-webcam.nix;[...]</span></span>
<span class="line"><span>services.udev.extraRules = &#39;&#39;</span></span>
<span class="line"><span>  ACTION==&quot;add&quot;,  \\</span></span>
<span class="line"><span>  SUBSYSTEM==&quot;usb&quot;, \\</span></span>
<span class="line"><span>  ATTR{idVendor}==&quot;04a9&quot;, \\</span></span>
<span class="line"><span>  ATTR{idProduct}==&quot;317b&quot;,  \\</span></span>
<span class="line"><span>  RUN+=&quot;\${startWebcam}/bin/start-webcam&quot;&#39;&#39;;[...]</span></span></code></pre></div><p>最后，在你的 <code>start-webcam</code> systemd 服务中删除 <code>wantedBy = [&quot;multi-user.target&quot;];</code> 这一行。（如果保留它，则无论相机是否开启，该服务都会在下次重启时自动启动。）</p><h3 id="重复使用旧技术" tabindex="-1">重复使用旧技术 <a class="header-anchor" href="#重复使用旧技术" aria-label="Permalink to “重复使用旧技术”">​</a></h3><p>我希望这篇文章能让你在放弃一些旧技术之前三思而后行。Linux 可以为技术注入活力，无论是你的电脑还是数码相机或其他外围设备等简单的东西。</p><hr>`,58)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/22/12/old-camera-webcam-linux"},{default:p(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/22/12/old-camera-webcam-linux",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/tomoliver"},{default:p(()=>[...s[5]||(s[5]=[a("Tom Oliver",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),i(e,{href:"https://github.com/lkxed"},{default:p(()=>[...s[6]||(s[6]=[a("lkxed",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),i(e,{href:"https://github.com/Pabloxllwe"},{default:p(()=>[...s[7]||(s[7]=[a("Pabloxllwe",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const y=l(c,[["render",h]]);export{x as __pageData,y as default};
